functions.castom_abs:
int castom_abs(int x)
{
    return x > 0 ? x : -x;
}

functions.castom_acos:
long double castom_acos(double x)
{
    return 3.14159265358979323846264338327950288 / 2 - castom_asin(x);
}

functions.castom_asin:
long double castom_asin(double x)
{
    long double term = x, sum = 0.0 / 0.0;
    if (-1.0 < x && x < 1.0)
    {
        sum = term;
        x *= x;
        for (int k = 1; castom_fabs(term) > 1e-10; k += 2)
            sum += (term *= x * k / (k + 1)) / (k + 2);
    }
    else if (x == 1.0)
    {
        sum = 3.14159265358979323846264338327950288 / 2.0;
    }
    else if (x == -1.0)
    {
        sum = -3.14159265358979323846264338327950288 / 2.0;
    }
    return sum;
}

functions.castom_atan:
long double castom_atan(double x)
{
    return castom_asin(x / castom_sqrt(1.0 + x * x));
}

functions.castom_ceil:
long double castom_ceil(double x)
{
    if (x >= 0x7fffffffffffffffLL || x <= (-0x7fffffffffffffffLL - 1LL) || x != x)
    {
        return (long double)x;
    }
    long double truncation = (long long)x;
    return truncation + (truncation < x);
}

functions.castom_cos:
long double castom_cos(double x)
{
    x = castom_fmod(x, 2.0 * 3.14159265358979323846264338327950288);
    long double t_s = 0, last = 1;
    for (int k = 1; castom_fabs(last) > 1e-10; ++k)
    {
        t_s += last;
        last *= -x * x / (2.0 * k - 1.0) / (2.0 * k);
    }
    return t_s;
}

functions.castom_exp:
long double castom_exp(double x)
{
    long double sum = 1.0;
    long double cur = 1.0;
    unsigned int n = 1;
    while (castom_fabs(cur) > 1e-10)
    {
        sum += (cur *= ((long double)x) / n++);
    }
    return sum;
}

functions.castom_fabs:
long double castom_fabs(double x)
{
    return x > 0.0 ? (long double)x : -(long double)x;
}

functions.castom_floor:
long double castom_floor(double x)
{
    if (x >= 0x7fffffffffffffffLL || x <= (-0x7fffffffffffffffLL - 1LL) || x != x)
    {
        return (long double)x;
    }
    long double truncation = (long long)x;
    return truncation - (truncation > x);
}

functions.castom_fmod:
long double castom_fmod(double x, double y)
{
    return (long double)(x - castom_trunc(x / y) * y);
}

functions.castom_pow:
long double castom_pow(double base, double exp)
{
    long double result;
    if (base == 0.0 && exp != 0.0)
    {
        result = 0.0;
    }
    else if (exp < 0)
    {
        result = castom_pow(1 / base, -exp);
    }
    else if (base < 0.0 && exp != (long)exp)
    {
        result = -0.0 / 0.0;
    }
    else if (exp == 0.0)
    {
        result = 1.0;
    }
    else
    {
        long double flag = 1.0;
        if (base < 0 && (long)exp % 2)
        {
            flag = -1.0;
        }
        if (base < 0)
            base = -base;
        long div = (long)exp;
        long double integerPart = 1;
        for (int i = 0; i < div; i++)
            integerPart *= base;
        result = integerPart * castom_exp((exp - (double)div) * castom_log(base)) * flag;
    }
    return result;
}

functions.castom_sin:
long double castom_sin(double x)
{
    x = castom_fmod(x, 2.0 * 3.14159265358979323846264338327950288);
    long double sum = 0.0;
    for (int i = 0; i <= 20; i++)
    {
        double fa = 1.0, pow = 1.0;
        for (int j = 1; j <= 2 * i + 1; j++)
        {
            fa *= j;
            pow *= x;
        }
        sum += ((i % 2 ? -1.0 : 1.0) / fa) * pow;
    }
    return sum;
}

functions.castom_sqrt:
long double castom_sqrt(double x)
{
    if (x != x || x < 0)
        return 0.0 / 0.0;
    double sqrt, temp;
    sqrt = x / 2;
    temp = 0;
    while (sqrt != temp)
    {
        temp = sqrt;
        sqrt = (x / temp + temp) / 2;
    }
    return sqrt;
}

functions.castom_trunc:
long double castom_trunc(double x)
{
    return (x > 0.0) ? castom_floor(x) : castom_ceil(x);
}

